custom_css:
/* ==========================================================
   MoodTube theme: Jewel Case  (theme format v2)
   CD playlist cover look: black jewel case with clear corner tabs and
   hinge notches, a big CD whose "print" is the track cover, a clear hub
   and light glints. Monochrome silver on black, mono type.
   Flow layout only, so it holds at any player size.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&display=swap');

@keyframes jc-spin { to { transform: rotate(360deg); } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --jc-black:  #0a0a0b;
    --jc-case:   #141416;
    --jc-silver: #e9ecf2;
    --jc-dim:    #9a9ea8;
    --jc-line:   rgba(255, 255, 255, 0.28);
    --jc-glass:  rgba(255, 255, 255, 0.06);
    --mt-text: var(--jc-silver);
    --mt-text-dim: var(--jc-dim);
    --mt-text-on-accent: #0a0a0b;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: rgba(255, 255, 255, 0.3);
    --mt-slider-track-height: 1px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 10px;
    --mt-slider-thumb-bg: var(--jc-black);
    --mt-slider-thumb-bg-hover: #2a2a2e;
    --mt-slider-thumb-border: 1.5px solid var(--jc-silver);
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--jc-silver);
}
.mt-volume {
    --mt-slider-track: rgba(255, 255, 255, 0.3);
    --mt-slider-track-height: 1px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 8px;
    --mt-slider-thumb-bg: var(--jc-silver);
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--jc-silver);
}

/* ---------- Case ---------- */
.mt-player {
    container-type: size;
    padding: 34px 18px 16px;
    background: var(--jc-black);
    border: 1px solid var(--jc-line);
    border-radius: 16px;
    color: var(--jc-silver);
    font-family: 'Space Mono', 'Courier New', monospace;
    box-shadow: inset 0 0 0 5px var(--jc-case), inset 0 0 0 6px rgba(255, 255, 255, 0.14);
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* clear plastic corner tabs */
.mt-player::before {
    content: ''; position: absolute; inset: 0; z-index: 1; pointer-events: none; opacity: 0.55;
    background:
        linear-gradient(#fff, #fff) 9px 9px / 16px 1px no-repeat,
        linear-gradient(#fff, #fff) 9px 9px / 1px 16px no-repeat,
        linear-gradient(#fff, #fff) calc(100% - 9px) 9px / 16px 1px no-repeat,
        linear-gradient(#fff, #fff) calc(100% - 9px) 9px / 1px 16px no-repeat,
        linear-gradient(#fff, #fff) 9px calc(100% - 9px) / 16px 1px no-repeat,
        linear-gradient(#fff, #fff) 9px calc(100% - 9px) / 1px 16px no-repeat,
        linear-gradient(#fff, #fff) calc(100% - 9px) calc(100% - 9px) / 16px 1px no-repeat,
        linear-gradient(#fff, #fff) calc(100% - 9px) calc(100% - 9px) / 1px 16px no-repeat;
}
/* hinge notches on both sides */
.mt-player::after {
    content: ''; position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background:
        linear-gradient(rgba(255, 255, 255, 0.35), rgba(255, 255, 255, 0.35)) 2px 22% / 3px 11% no-repeat,
        linear-gradient(rgba(255, 255, 255, 0.35), rgba(255, 255, 255, 0.35)) 2px 66% / 3px 11% no-repeat,
        linear-gradient(rgba(255, 255, 255, 0.35), rgba(255, 255, 255, 0.35)) calc(100% - 2px) 22% / 3px 11% no-repeat,
        linear-gradient(rgba(255, 255, 255, 0.35), rgba(255, 255, 255, 0.35)) calc(100% - 2px) 66% / 3px 11% no-repeat;
}

/* ---------- Header ---------- */
.mt-player-header { top: 14px; left: 22px; right: 96px; align-items: center; }
.mt-player-header-title { color: var(--jc-silver); font-size: 9px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; }
.mt-player-status { color: var(--jc-dim); opacity: 1; font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; }
.mt-window-btn {
    top: 10px; width: 20px; height: 20px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 9px; color: var(--jc-silver);
    background: transparent; border: 1px solid var(--jc-line); border-radius: 5px;
}
.mt-btn-search { right: 66px; }
.mt-btn-settings { right: 40px; }
.mt-btn-close { right: 14px; }
.mt-resize-handle i { color: rgba(255, 255, 255, 0.3); }

/* ---------- The disc ---------- */
.mt-player .mt-player-body { gap: 9px; }
.mt-cover {
    width: 148px; height: 148px; box-sizing: border-box;
    border: 2px solid rgba(255, 255, 255, 0.55); border-radius: 50%; background: #050506;
    box-shadow: 0 0 0 5px rgba(255, 255, 255, 0.06);
}
.mt-cover-img { background: #1b1b1f; }
.mt-player.mt-is-playing .mt-cover-img { animation: jc-spin 9s linear infinite; }
/* glints stay still while the print spins */
.mt-cover::after {
    content: ''; position: absolute; inset: 0; z-index: 2; border-radius: 50%; pointer-events: none;
    background:
        conic-gradient(from 25deg, rgba(255, 255, 255, 0) 0deg, rgba(255, 255, 255, 0.34) 36deg, rgba(255, 255, 255, 0) 78deg,
                       rgba(255, 255, 255, 0) 180deg, rgba(255, 255, 255, 0.28) 216deg, rgba(255, 255, 255, 0) 260deg),
        radial-gradient(circle, transparent 0 27%, rgba(255, 255, 255, 0.14) 27.5% 30%, transparent 30.5%);
}
/* clear hub with the centre hole */
.mt-cover-hole {
    z-index: 3; width: 44px; height: 44px; box-sizing: border-box;
    border: 1px solid rgba(255, 255, 255, 0.65);
    background: radial-gradient(circle, var(--jc-black) 0 7px, rgba(255, 255, 255, 0.22) 7.5px);
}

/* ---------- Track ---------- */
.mt-track-title { color: #ffffff; font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 1px; }
.mt-track-subtitle { color: var(--jc-dim); font-size: 9px; font-weight: 400; letter-spacing: 0.12em; text-transform: uppercase; }
.mt-btn-favorite { color: var(--jc-silver); font-size: 12px; }

/* ---------- Progress ---------- */
.mt-progress { margin-top: 0; }
.mt-time { color: var(--jc-dim); font-size: 9px; letter-spacing: 0.06em; }

/* ---------- Buttons ---------- */
.mt-controls { gap: 9px; }
.mt-controls > .mt-btn {
    width: 30px; height: 30px; box-sizing: border-box; display: flex; align-items: center; justify-content: center;
    font-size: 11px; color: var(--jc-silver);
    background: var(--jc-glass); border: 1px solid var(--jc-line); border-radius: 50%;
}
.mt-controls > .mt-btn-play { width: 40px; height: 40px; font-size: 14px; color: var(--jc-black); background: var(--jc-silver); border-color: var(--jc-silver); }
.mt-controls > .mt-btn:hover { transform: none; background: rgba(255, 255, 255, 0.16); color: #ffffff; }
.mt-controls > .mt-btn-play:hover { background: #ffffff; color: var(--jc-black); }
.mt-btn-ai.mt-is-busy { color: #ffffff; }
.mt-volume-icon { color: var(--jc-dim); font-size: 10px; }

/* wide bar: tighter parts so everything fits in one row */
.mt-player.moodtube-row-layout .mt-player-body { gap: 8px; }
.mt-player.moodtube-row-layout .mt-cover { box-shadow: none; }
.mt-player.moodtube-row-layout .mt-cover-hole { border-width: 1px; background: var(--jc-black); }
.mt-player.moodtube-row-layout .mt-track-info { flex: 1 1 100px; min-width: 60px; padding-right: 20px; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 11px; }
.mt-player.moodtube-row-layout .mt-time-total { display: none; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 100px; min-width: 80px; }
.mt-player.moodtube-row-layout .mt-controls { gap: 3px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 24px; height: 24px; font-size: 9px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 30px; height: 30px; font-size: 11px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 70px; min-width: 48px; }
.mt-player.moodtube-row-layout .mt-volume-high { display: none; }

/* ---------- Queue / playlists ---------- */
.mt-panel { background: rgba(10, 10, 11, 0.96); padding-top: 40px; border-radius: inherit; }
.mt-panel-title { color: var(--jc-silver); font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--jc-silver); }
.mt-queue-item { background: var(--jc-glass); border-color: rgba(255, 255, 255, 0.12); border-radius: 8px; }
.mt-queue-item:hover { background: rgba(255, 255, 255, 0.12); }
.mt-queue-item.mt-is-current { background: rgba(255, 255, 255, 0.1); border-color: var(--jc-silver); }
.mt-queue-thumb { border-radius: 50%; }
.mt-queue-thumb.mt-is-empty { background: rgba(255, 255, 255, 0.14); }
.mt-queue-title { color: var(--jc-dim); font-size: 11px; }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: #ffffff; }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #e9707a; }
.mt-queue-now, .mt-queue-add { color: var(--jc-silver); }
.mt-queue-dislike { background-color: var(--jc-silver); }
.mt-queue-empty { color: var(--jc-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: var(--jc-black); border-color: rgba(255, 255, 255, 0.55); box-shadow: none; color: var(--jc-silver);
}

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.4) transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 6px; height: 6px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.4); border-radius: 3px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(0, 0, 0, 0.7);
    --mt-modal-shadow: none;
    --mt-text-strong: #ffffff;
    --mt-divider: rgba(255, 255, 255, 0.1);
}
#mt-settings-modal .mt-flex-container { border: 1px solid var(--jc-line); border-radius: 16px; box-shadow: inset 0 0 0 5px var(--jc-case); }
#mt-settings-modal .mt-header h3 { font-size: 1em; letter-spacing: 0.2em; text-transform: uppercase; }
#mt-settings-modal .mt-close { color: var(--jc-silver); }
#mt-settings-modal .mt-tag { background-color: var(--jc-glass); border-color: var(--jc-line); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: rgba(255, 255, 255, 0.14); border-color: var(--jc-silver);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--jc-silver); border-color: var(--jc-silver); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: var(--jc-glass); border-color: var(--jc-line); }
#mt-settings-modal .mt-btn-test:hover { background: rgba(255, 255, 255, 0.14); border-color: var(--jc-silver); }
#mt-settings-modal .mt-subpanel { background: rgba(255, 255, 255, 0.04); }

/* ---------- Search panel and playlists (added to the extension later) ---------- */

.mt-panel-search { --mt-bg-primary: #0a0a0b; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #0a0a0b) !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--jc-silver); --mt-pl-spotify-tab-text: #0a0a0b; }
.mt-btn-favorite.mt-is-active { color: #ffffff; }
.mt-pl-tabs { background: var(--jc-glass); border: 1px solid rgba(255, 255, 255, 0.12); }
.mt-pl-tool { background: var(--jc-glass); border-color: var(--jc-line); color: var(--jc-silver); }
.mt-pl-tool:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-tool.mt-pl-play { background: var(--jc-silver); border-color: var(--jc-silver); color: #0a0a0b; }
.mt-pl-inline-cancel { background: var(--jc-glass); color: var(--jc-silver); }
.mt-pl-cover-empty { background: rgba(255, 255, 255, 0.1); color: var(--jc-dim); }
.mt-pl-modal { --mt-overlay: rgba(0, 0, 0, 0.7); }
.mt-pl-modal-box { background: var(--jc-black); border: 1px solid var(--jc-line); border-radius: 16px; box-shadow: inset 0 0 0 5px var(--jc-case); }
.mt-pl-modal-track { border-bottom-color: rgba(255, 255, 255, 0.12); }
.mt-pl-option { background: var(--jc-glass); }
.mt-pl-option:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--jc-silver); }

/* the header has less room now (search, settings, close): drop the status text in a narrow window */
@container (max-width: 300px) { .mt-player .mt-player-status { display: none; } }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Space Mono', 'Courier New', monospace;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: 92px; }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 7px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 11px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 43px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 75px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 107px; left: auto; }
/* == /window buttons == */
